// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb7", fn: function () { return String(dma_ListInvstgComDetail.get("dpFromEmpCnt")) + " 명"; } },
        { childId: "a_157", fn: function () { return String(dma_ListInvstgComDetail.get("hpage")); } },
        { childId: "__rb12", fn: function () { return String(dma_ListInvstgComDetail.get("dpFromAcntclsMmdd")) + " 월"; } },
        { childId: "__rb20", fn: function () { return String(dma_ListInvstgComDetail.get("dpFromLgshrhdRto")) + " %"; } },
        { childId: "__rb23", fn: function () { return String(dma_ListInvstgComDetail.get("dpFromListShrs")) + " 주"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

